"""Run with Python 3, Git, Maven >=3.9, and JDK 17; no publishing credentials needed."""

from datetime import datetime, timezone
import hashlib
import os
from pathlib import Path
import re
import subprocess
import tempfile
import unittest
import xml.etree.ElementTree as ET
import zipfile


ROOT = Path(__file__).resolve().parents[2]
COMMIT_DATE = "2031-01-01T00:30:00+14:00"
EXPECTED_DATE = datetime.fromisoformat(COMMIT_DATE).astimezone(timezone.utc)


class ReleaseTimestampTest(unittest.TestCase):
    def setUp(self):
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        self.root = Path(directory.name)
        self.env = os.environ.copy()
        self.env.pop("MAVEN_ARGS", None)
        self.env.update({
            "GITHUB_ENV": str(self.root / "github-env"),
            "GIT_AUTHOR_NAME": "Release test",
            "GIT_AUTHOR_EMAIL": "release-test@example.com",
            "GIT_COMMITTER_NAME": "Release test",
            "GIT_COMMITTER_EMAIL": "release-test@example.com",
            "GIT_AUTHOR_DATE": "2020-01-01T00:00:00Z",
            "GIT_COMMITTER_DATE": COMMIT_DATE,
        })
        self.run_command(["git", "init", "--quiet"])
        self.run_command(["git", "-c", "commit.gpgsign=false", "commit",
                          "--allow-empty", "--quiet", "-m", "Release fixture"])

    def run_command(self, command):
        result = subprocess.run(command, cwd=self.root, env=self.env, text=True,
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=180)
        self.assertEqual(result.returncode, 0, result.stdout)

    def set_release_environment(self):
        self.run_command(["bash", str(ROOT / ".github/scripts/set_release_timestamp.sh")])
        return dict(line.split("=", 1) for line in (self.root / "github-env").read_text().splitlines())

    def test_uses_committer_timestamp_instead_of_author_or_wall_clock(self):
        self.assertEqual(self.set_release_environment(), {
            "MAVEN_ARGS": f"-Dproject.build.outputTimestamp={int(EXPECTED_DATE.timestamp())}"
        })

    def test_javadoc_uses_release_year_and_is_reproducible(self):
        # Copy the SDK's actual Javadoc plugin configuration into a dependency-free fixture.
        namespace = {"m": "http://maven.apache.org/POM/4.0.0"}
        plugin = ET.parse(ROOT / "pom.xml").find(
            "m:build/m:pluginManagement/m:plugins/m:plugin"
            "[m:artifactId='maven-javadoc-plugin']", namespace)
        self.assertIsNotNone(plugin)
        pom = ET.fromstring("""<project xmlns="http://maven.apache.org/POM/4.0.0">
  <modelVersion>4.0.0</modelVersion>
  <groupId>release.test</groupId><artifactId>timestamp-probe</artifactId><version>1</version>
  <properties>
    <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>
    <project.build.outputTimestamp>1980-02-01T00:00:00Z</project.build.outputTimestamp>
  </properties>
  <build><plugins/></build>
</project>""")
        pom.find("m:build/m:plugins", namespace).append(plugin)
        ET.register_namespace("", namespace["m"])
        ET.ElementTree(pom).write(self.root / "pom.xml", encoding="unicode")
        source = self.root / "src/main/java/Probe.java"
        source.parent.mkdir(parents=True)
        source.write_text("/** Release timestamp probe. */\npublic class Probe {}\n")

        # Apply GITHUB_ENV as Actions does, then let the real Maven process consume MAVEN_ARGS.
        self.env.update(self.set_release_environment())
        hashes = []
        for zone in ("UTC", "Pacific/Kiritimati"):
            with self.subTest(timezone=zone):
                self.env["TZ"] = zone
                self.run_command(["mvn", "-B", "-ntp", "clean", "javadoc:jar"])
                jar = self.root / "target/timestamp-probe-1-javadoc.jar"
                hashes.append(hashlib.sha256(jar.read_bytes()).hexdigest())
                with zipfile.ZipFile(jar) as archive:
                    pages = [archive.read(name).decode() for name in archive.namelist()
                             if name.endswith(".html")]
                    years = [year for page in pages
                             for year in re.findall(r"Copyright &#169; (\d{4})", page)]
                    self.assertTrue(years, "No copyright footers found")
                    self.assertEqual(set(years), {str(EXPECTED_DATE.year)})
                    self.assertFalse(any('name="dc.created"' in page for page in pages))
                    self.assertTrue(all("<!-- Generated by javadoc (17) -->" in page for page in pages))
                    self.assertEqual({entry.date_time for entry in archive.infolist()},
                                     {EXPECTED_DATE.timetuple()[:6]})
        self.assertEqual(hashes[0], hashes[1])


if __name__ == "__main__":
    unittest.main()
